from pathlib import Path
import pandas as pd,json,shutil
R=Path(__file__).resolve().parent;O=R/'results/v0';s=pd.read_csv(O/'summary.csv');cases=json.loads((R/'cases.json').read_text());a=pd.read_csv(O/'descriptive-comparison.csv')
def pc(x):return f'{x*100:+.2f}%'
def cell(x):return f'{pc(x.net_return)} / {x.max_drawdown*100:.2f}%'
lines=['# 多算法切换：有限探索结论（2026-10-24）','','[交互报告](http://127.0.0.1:8778/)｜[事前协议](PROTOCOL.md)｜[固定场景v1](../fixed-scenarios-v1/README.md)｜[全部账户](results/v0/summary.csv)｜[核账](results/v0/audit.json)','','**不支持将当前组合直接升为统一自动切换策略。** 本轮较有价值的证据是敏感退出后应单独评价重新入场资格；R减少了反复试错，但在牛市与黄金长趋势上损失参与，不能据今年半导体成功全面替代原算法。','','## 设计与执行','','固定11主场景：前轮9种历史环境＋今年半导体＋已研究半导体牛市；另7个证券2021-01-01—2026-10-16连续窗检查。固定场景不随结果换边界，标签不进入信号，场景/连续窗重叠不当独立样本；所有历史均为开发材料。512480代表半导体，不称全部成分股。2026完整半导体实际1月5日—10月23日，24日周六。','','8策略＋被动×18窗×3执行情景=486账户，一次冻结、结果后规则修订0。基准E0/E2与上一轮66个账户逐日净值及交易完全复现。新R家族由当日影子状态独立运行，无任何未来E0实际成交表；今年R恰好复现此前M的六笔结果，这一结论不是将M撮合表用作信号。','','- E0原量价结构；E2原入场＋2ATR敏感退出。','- R：E2退出后，等影子E0先结束再新建立才能重入。原始首次参与证据不加缠论门槛。','- RC：R基础上，E0仍存续时当日新确认有效二买允许重入。卖出不额外加缠论卖点。','- RF：R基础上，已有拟合候选的当日新启动允许重入。','- G（事前指定主要候选）：R的重入规则；63日量价方向>0用E0退出，否则E2。量通过归一活跃权重影响真实方向开关，价格相同量变化可改变规则；不读取事后环境标签，也不把持仓当趋势。','- C2：CZSC1.0.2日线6/100笔，SMA21辅助二买；已知笔低点破坏或原生一/二/三卖退出；确认日记信号，不倒填端点。这是特定价格型缠论实现，不代表全部缠论或量价主线。','- F：已有20日量价斜率＋2ATR＋永久旧峰记忆拟合候选，未重新选参；绝非趋势动物原算法，其旧峰假说早已被原图否定。作为可识别的既有对照保留。','','E0/E2/R家族在独立窗首继承同一个前日E0状态，与前轮一致；F/C2继承各自全历史预热状态。窗口重置与真实连续持仓不同，因此额外连续窗必须一起读。','','每个账户初始1，多头/现金，无杠杆，不每日等权再平衡；每边5bp费＋5bp不利滑点，另成本加倍与多延迟一日压力。收盘知信号、下一可观察开盘成交；买入跳空破支持取消，卖单锁定；固定末日行政清算另列，非算法卖顶。港股税费/汇率/手数、分数份额及流动性仅统一研究代理，不宣称可执行实盘。','','## 固定主场景基础结果','','每格为**净收益 / 最大回撤**，均扣成本。','','| 场景及区间 | E0原算法 | E2敏感退出 | R重建重入 | RC加二买 | G慢背景切换 |','|---|---:|---:|---:|---:|---:|']
for c in cases:
 if c['role']!='fixed_scenario':continue
 z=s[(s.case==c['id'])&(s.scenario=='base')].set_index('policy');lines.append('| '+c['name']+' '+c['type']+' '+c['start']+'—'+c['end']+' | '+' | '.join(cell(z.loc[p]) for p in ['E0','E2','R','RC','G'])+' |')
lines+=['','![固定11场景](charts/fixed-comparison.png)','','## 连续历史：防止只靠切窗得到好结论','','每个标的单独运行2021年起至2026-10-16，不按年度重置；同样不是全市场股票池策略。','','| 标的 | E0 | E2 | R | RC | G |','|---|---:|---:|---:|---:|---:|']
for c in cases:
 if c['role']!='continuous_check':continue
 z=s[(s.case==c['id'])&(s.scenario=='base')].set_index('policy');lines.append('| '+c['name']+' | '+' | '.join(cell(z.loc[p]) for p in ['E0','E2','R','RC','G'])+' |')
lines+=['','R在7个连续窗中4个收益高于E0、7个回撤低于E0；但黄金ETF从E0的+83.15%变成−15.61%，说明严格阻止重入会让持续大趋势断档。R连续半导体回撤29.15%，京东62.81%，没有实现20%回撤目标；不可用案例平均回撤冒充整户最大回撤。','','## 机制：为什么有时好，有时坏','','**今年半导体：反复买回吞噬退出优势。** R收益54.82%/回撤21.52%，6笔自然交易、胜率50%；E2收益7.87%/回撤37.40%，10笔/30%。R的主要变化是去掉同一原结构中的额外试错，并非知道6月顶部。RC新增2026-02-10、06-04、07-09三次二买重入全部亏损，净交易收益约−5.70%、−3.13%、−5.84%；后来资金因复利不同，不能把这三个百分比直接相加当账户损耗。RC降到33.16%/26.11%。详见[额外重入逐笔](results/v0/RC-additional-entry-legs.csv)。','','**牛市：退出后完全等待也会伤害大赢家。** 2025-04-10原入场E0持到11-13获39.41%；R于05-16获0.79%即退出，等到12月新结构才有资格。RC的7月/9月二买补回部分行情，牛市账户从R106.48%补至151.89%，但仍低于E0的162.01%。G慢方向在2025-05-16转弱、次开盘退出，随后相同重入锁定使它无法在原结构继续时回来，最终89.61%；不能称慢背景已识别真实牛市。','','**黄金长趋势：关键反例。** 原算法2024-08-20—2025-10-23同一段净交易收益62.59%，R在2024-09-05以−0.72%早退，之后长时间没有新原结构。G也没有解决，连续黄金账户−8.31%。这些失败不能用正常浮盈回吐的解释盖掉，也不能因减小回撤就算成功。','','**RF并未提供可靠增量。** 11固定窗与R多数相同，少量额外启动使平均收益15.93%→15.44%；连续窗R13.55%→RF11.76%。F独立在主场景平均持有时间仅5.13%，11例中7例零交易；其低回撤主要来自少参与/永久旧峰禁入，不是优异宏观辨识，不能把8/9盈利交易的高胜率当证据。','','## 费用、延迟、胜率和收益结构','','下表为**11案例分别初始1的描述性均值**，不是可投资组合；窗口长度不一且重叠。平均回撤不是组合回撤。','','| 情景 | 策略 | 案例均值收益 | 案例均值最大回撤 |','|---|---|---:|---:|']
for sc in ['base','cost2','delay1']:
 for p in ['E0','E2','R','RC','G']:
  x=a[(a.role=='fixed_scenario')&(a.scenario==sc)&(a.policy==p)].iloc[0];lines.append(f'| {sc} | {p} | {pc(x.case_mean_return)} | {x.case_mean_drawdown:.2%} |')
lines+=['','R在基础、成本加倍、多延迟一日均7/11例同时改善收益与回撤，11/11例回撤降低；这不是未来成功概率。多延迟一日今年R收益48.44%/回撤28.32%，基础收益幅度与风险不能照搬。RC案例均值基础略高，成本/延迟后弱于R；G三种情景均值都弱于E0。','','基础11窗E0/R的合并交易胜率40.91%/48.48%，包含期末行政清算且有重叠，不能作独立概率估计。自然交易胜率、清算笔数等逐账户见CSV/交互报告。R平均持有36.95%时间，E0为78.11%，减小暴露是回撤改善的重要来源，不能线性放大仓位后宣称同风险优势。','','R主场景普通交易净贡献案例均值−0.04%看似相抵，但连续7窗为−17.17%，尾部贡献30.71%，尚未达到普通交易成本后基本相抵。主场景选择本身已看过且包含强牛，不能只引用好看的一个数字。30%只是成本后闭合交易分类，不是止盈。','','## 理论和宏观选项','','[AQR原文](https://www.aqr.com/insights/research/journal-article/a-century-of-evidence-on-trend-following-investing)支持跨反应尺度趋势研究，[Faber作者原文](https://mebfaber.com/2009/02/19/a-quantitative-approach-to-tactical-asset-allocation-updated/)讨论简单均线择时；两者只是机制启发，不证明本轮股票/ETF多头组合，也不是本轮参数效果的来源。','','宏观本轮未接入交易信号：本地没有按发布日期和修订版本保存的宏观历史库。用户允许探索宏观，但不能把今天的修订值填进过去；[ALFRED官方说明](https://fred.stlouisfed.org/docs/api/fred/alfred.html)展示了真实发布/修订版本的要求。没有宏观回测结果，不据此声称宏观有效或无效。市场牛熊的事后命名也不能代替当时可得指标。','','## 裁决和方案','','1. **固定场景v1登记并继续保留**：原数据哈希和边界冻结，新数据不得静默覆盖。它是固定检查清单，不能被反复优化成训练答案。','2. **主要候选G不晋升**：慢量价方向切换宽/窄退出没有可靠解决“整理还是转熊”的识别，整体收益和关键大趋势受损。','3. **保留E0冻结基准，R作为独立风险取舍对照**：R有控制重试损耗的证据，但错过长期趋势的反例严重，不全面替换，不自动用于实盘。','4. **RC/RF不升为默认恢复通道**：二买在部分牛市补回收益，也重新引入熊市/震荡亏损；拟合启动缺乏稳定增量。不能事后给半导体牛市用RC、下跌用R、黄金用E0拼最优策略。','5. 本轮结束，不追加阈值、宏观因子或组合搜索，不恢复旧全市场队列、不重置项目停止计数。若以后明确恢复，值得提出的有限问题是“早退出后，怎样以新的量价结构证据恢复参与，同时限制累计试错”；本轮尚未解决，不能称已有最终交易系统。','','## 审核与复现','','[协议](PROTOCOL.md)、[账户前原始量价/状态图检](review-before-accounts.json)、[冻结](freeze.json)、[186项精确前缀检查](prefix-checks.csv)、[独立核账](results/v0/audit.json)。原始7数据复用前轮，没有新增行情下载、认证访问或微信操作。261冻结文件未变，14,832笔买卖独立重建现金、份额、费用/滑点与净值，最大NAV误差1.12e-14；E0/E2旧66账户逐日/逐交易恒等。','','不要直接重跑prepare/freeze/run：它们有独立结果目录保护，重跑需新目录和授权。核账可只读执行：','','```sh','CZSC_HOME="$PWD/.tools/czsc/cache" MPLCONFIGDIR=/private/tmp/switch-mpl .tools/czsc/.venv/bin/python research_rounds/strategy-switching-20261024/audit.py','```','','本轮486与前轮240/24/507/黄金39分别计数，不将它们误称一轮样本外验证。所有失败结果、原算法及旧报告均保留。']
